  { codigoDealer: '00900', dealer: 'SIMOTOR IBAGUÉ', nombrePilot: 'Simotor - Ibagué', mailPilot: 'simotor.ibague@ford.com', aliases: ['Ford Ibagué'] },
];
// Sucursales de get_sucursales SIN dealer en el CSV (quedan sin match):
// Ford Armenia, Ford Cúcuta, Ford Popayán, Ford Sincelejo.

// minúsculas, sin tildes, sin espacios ni caracteres especiales
const norm = (s) =>
  String(s ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');

// Todos los datos que llegan del trigger
const trigger = $('When Executed by Another Workflow').first().json;
const sucursal = trigger.sucursal;
const buscado = norm(sucursal);

// Match: primero coincidencia exacta; si no, include en cualquier sentido.
// Se compara contra Dealer, Nombre PILOT y alias.
let mejor = null;
let mejorScore = Infinity;

if (buscado) {
  for (const d of dealers) {
    const nombres = [d.dealer, d.nombrePilot, ...d.aliases].map(norm).filter(Boolean);
    let scoreDealer = Infinity;

    for (const n of nombres) {
      if (n === buscado) {
        scoreDealer = Math.min(scoreDealer, 0); // exacta
      } else if (buscado.includes(n) || n.includes(buscado)) {
        scoreDealer = Math.min(scoreDealer, 1 + Math.abs(n.length - buscado.length));
      }
    }

    if (scoreDealer < mejorScore) {
      mejorScore = scoreDealer;
      mejor = d;
    }
  }
}

const resultado = {
  dealerEncontrado: !!mejor,
  sucursalBuscada: sucursal ?? null,
  codigoDealer: mejor?.codigoDealer ?? null,
  dealer: mejor?.dealer ?? null,
  nombrePilot: mejor?.nombrePilot ?? null,
  mailPilot: mejor?.mailPilot ?? null,
};

// Un solo item: todos los datos del trigger + el resultado del match
return [{ json: { ...trigger, ...resultado } }];

