// El grado de interés llega en el trigger (close_conversation), no en la fila de la BDD.
const trigger = $('When Executed by Another Workflow').first().json;
const item = $input.first().json;

// Conservar los campos del lead (fila BDD)
const resultado = { ...item };

const gradoInteresId = String(trigger.gradoInteresId ?? "").trim();
const gradoInteres = String(trigger.gradoInteres ?? "").trim();

const mapaInteres = {
  "1": "Frío",
  "3": "Tibio",
  "07B7AC5A": "Caliente"
};

// Normaliza el nombre (por si llega sin id): quita tildes y pasa a minúsculas
const norm = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const mapaNombre = { "frio": "Frío", "tibio": "Tibio", "caliente": "Caliente" };

// El nombre manda: el bot a veces manda nombre y codigo que no coinciden (ej. "Frío" con 07B7AC5A).
const codigoPorNombre = { "Frío": "1", "Tibio": "3", "Caliente": "07B7AC5A" };
if (mapaNombre[norm(gradoInteres)]) {
  const v = mapaNombre[norm(gradoInteres)];
  resultado.interes_valor = v;
  resultado.rason = `Se asigna interés ${v} según gradoInteres recibido ("${gradoInteres}").`;
} else if (mapaInteres[gradoInteresId]) {
  resultado.interes_valor = mapaInteres[gradoInteresId];
  resultado.rason = `Se asigna interés ${mapaInteres[gradoInteresId]} porque gradoInteresId es ${gradoInteresId}.`;
} else {
  resultado.interes_valor = "Frío";
  resultado.rason = `Se asigna interés Frío por defecto porque gradoInteresId (${gradoInteresId || "vacío"}) y gradoInteres (${gradoInteres || "vacío"}) no coinciden con ningún valor configurado.`;
}
resultado.interes_id = codigoPorNombre[resultado.interes_valor];

return [{ json: resultado }];

